#include <iostream>

class Percentage {
 public:
  bool set(int value) {
    if (value < 0 || value > 100) return false;
    value_ = value;
    return true;
  }
  int value() const { return value_; }

 private:
  int value_ = 0;
};

int main() {
  Percentage p;
  std::cout << p.set(80) << ' ' << p.set(120) << ' ' << p.value();
}
